                return;
            reason = L"TEXT_QST_018_QUEST_FAILED_CHIEF_DIED";
        } else if (ReasonForFailure == 3) {
            if (IsActiveThreadTerminating())
                return;
            reason = L"TEXT_QST_018_QUEST_FAILED_PRISONER_ESCAPED";
        } else {
            if (IsActiveThreadTerminating())
                return;
