    Game->EnableDecals(true);
    Game->Pause(0.1f);
    Game->FadeScreenIn();
    while (Game->IsRegionLoaded("KnotholeGlade") != false) {
        Game->NewScriptFrame();
        if (IsActiveThreadTerminating())
            return;
    }
    if (IsActiveThreadTerminating())
        return;
    Game->DeactivateQuestLater(Game->GetActiveQuestName(), 0);
