    for (int i = 0; i < 5; ++i) { char b[8]; std::sprintf(b, "N%d", i); s.SpySpeechNormal[i] = b; std::sprintf(b, "R%d", i); s.SpySpeechRandom[i] = b; }
    g_spyDiesAt = 7;
    CScriptThing spy; spy.spy = true;
    s.WatchForSpySpeechMarkers(spy);
