    bool ok = g_lines.size() == 4 && g_lines[0] == "N0" && g_lines[3] == "N3" && s.SpeechSpyCount == 4 && g_timer == 0xa50;
    g_lines.clear(); g_frames = 0; g_spyDiesAt = 1000; s.SpeechSpyCount = 5; s.EnableSpeechSpy = true;
    g_spyDiesAt = 4;
    s.WatchForSpySpeechMarkers(spy);
