    ok = ok && g_lines.size() == 2 && g_lines[0] == "R1" && g_lines[1] == "R4" && s.lastRandomSpySpeechIdx == 4;
    if (!ok) { std::printf("00f0ef60_TEST FAIL\n"); return 1; }
